import type { CategoryExportData } from 'redux/api/bff';

export function buildGlobalDataForPeriod(
  categories: Record<string, CategoryExportData> | undefined,
) {
  return {
    global: categories?.['All'],
    megabrands: categories?.['Megabrands'],
    mainstream: categories?.['Mainstream'],
    core: categories?.['Core+'],
    premiumization: categories?.['Premiumization'],
    expansion: categories?.['Expansion'],
    sustain: categories?.['Sustain'],
    tail: categories?.['Tail'],
    globalBrands: categories?.['All Global Brands'],
    corona: categories?.['Corona'],
    budweiser: categories?.['Budweiser'],
    michelobUltra: categories?.['Michelob Ultra'],
    stellaArtois: categories?.['Stella Artois'],
    heineken: categories?.['Heineken'],
    contribution: {
      global: categories?.['All']?.topCountryContribution,
      megabrands: categories?.['Megabrands']?.topCountryContribution,
    },
    trendPowerEvolutionData: {
      global: categories?.['All']?.trendPowerEvolution,
      megabrands: categories?.['Megabrands']?.trendPowerEvolution,
    },
  };
}

export function mergeGroupCategories(
  groups: (Record<string, CategoryExportData> | undefined)[],
): Record<string, CategoryExportData> | undefined {
  const result: Record<string, CategoryExportData> = {};
  let hasAny = false;

  for (const group of groups) {
    if (group) {
      hasAny = true;
      Object.assign(result, group);
    }
  }

  return hasAny ? result : undefined;
}
